import{_ as t,o,c as n,a5 as a}from"./chunks/framework.BYXPg_yw.js";const b=JSON.parse('{"title":"Connecting the Robot to the Internet","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/operation/robot-internet.md","filePath":"manual/operation/robot-internet.md","lastUpdated":1793350928000}'),i={name:"manual/operation/robot-internet.md"};function s(r,e,c,h,d,l){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="connecting-the-robot-to-the-internet" tabindex="-1">Connecting the Robot to the Internet <a class="header-anchor" href="#connecting-the-robot-to-the-internet" aria-label="Permalink to &quot;Connecting the Robot to the Internet&quot;">​</a></h1><p>Remote check and remote app connection need the robot itself on the internet. The robot&#39;s router joins the site Wi-Fi as a client (wireless WAN, also called WISP) and shares that connection with the robot. A robot with its own USIM is already on the internet and can skip this page.</p><h2 id="before" tabindex="-1">Before you start <a class="header-anchor" href="#before" aria-label="Permalink to &quot;Before you start {#before}&quot;">​</a></h2><ul><li>The name and password of a site Wi-Fi network that reaches the internet.</li><li>A phone, tablet or PC on the robot&#39;s Wi-Fi (<code>RBQ_{XX}</code>).</li><li>The router admin password. Ask support if you do not have it.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>A network that needs a web sign-in page or device (MAC) registration does not work here. Use a phone hotspot instead — set it up the same way, picking the hotspot as the site Wi-Fi.</p></div></div><h2 id="open" tabindex="-1">Step 1: Open the router settings <a class="header-anchor" href="#open" aria-label="Permalink to &quot;Step 1: Open the router settings {#open}&quot;">​</a></h2><p>On a device on the robot&#39;s Wi-Fi, open <code>http://192.168.0.1</code> in a browser and sign in.</p><h2 id="wisp" tabindex="-1">Step 2: Turn on wireless WAN <a class="header-anchor" href="#wisp" aria-label="Permalink to &quot;Step 2: Turn on wireless WAN {#wisp}&quot;">​</a></h2><ol><li>Go to <code>무선랜 관리</code> › <code>무선 확장 설정</code>.</li><li>Under <strong>2.4GHz</strong>, choose <code>무선 WAN</code>. Do not choose <code>브리지</code> — it changes the robot&#39;s address.</li><li>Press the search button next to the network name, pick the site Wi-Fi, enter its password and press <code>적용</code>.</li><li>The 2.4GHz box shows <code>무선 WAN 연결됨</code> with the signal strength when it has joined.</li></ol><p>Leave <strong>5GHz</strong> at <code>중단</code>. If the robot&#39;s own Wi-Fi is on 5GHz, wireless WAN there can drop the controller&#39;s connection while it switches.</p><h2 id="dynamic-ip" tabindex="-1">Step 3: Use a dynamic address <a class="header-anchor" href="#dynamic-ip" aria-label="Permalink to &quot;Step 3: Use a dynamic address {#dynamic-ip}&quot;">​</a></h2><p>Go to <code>네트워크 관리</code> › <code>인터넷 설정 정보</code>. If <code>고정 IP 방식</code> is selected, the router still holds the address from a previous site and the internet will not work. Choose <code>동적 IP 방식</code> and press <code>적용</code>.</p><h2 id="check" tabindex="-1">Step 4: Check <a class="header-anchor" href="#check" aria-label="Permalink to &quot;Step 4: Check {#check}&quot;">​</a></h2><p>Open <strong>Maintenance</strong> › <code>Robot Check</code> in the app and scroll to <code>Remote check</code> at the bottom. When the robot reaches the internet the warning about the internet goes away and the turn-on buttons become active. If it stays, check the steps above or ask support.</p>',14)])])}const u=t(i,[["render",s]]);export{b as __pageData,u as default};
